/* Meesho Merchant concept. Every business, price, quote and transaction below is demo data. */
const STORE='meesho-merchant-demo-v1';
const iconPaths={search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4 4"/>',home:'<path d="m3 10 9-7 9 7v11h-6v-7H9v7H3Z"/>',bag:'<path d="M5 7h14l1 14H4L5 7Z"/><path d="M8 7V6a4 4 0 0 1 8 0v1"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',request:'<path d="M14 3H5v18h14V8Z"/><path d="M14 3v5h5M8 12h8M8 16h6"/>',orders:'<path d="m3 7 9-4 9 4v10l-9 4-9-4Z"/><path d="m3 7 9 4 9-4M12 11v10M7 5l10 4"/>',truck:'<path d="M2 6h12v12H2ZM14 10h4l4 5v3h-8"/><circle cx="6" cy="18" r="2"/><circle cx="18" cy="18" r="2"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',check:'<path d="m5 12 4 4L19 6"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',swap:'<path d="M3 7h17m-4-4 4 4-4 4M21 17H4m4-4-4 4 4 4"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9 9a3 3 0 0 1 6 0c0 2-3 2-3 4M12 17h.01"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Z"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6Z"/><path d="m8 12 3 3 5-6"/>',plus:'<path d="M12 4v16M4 12h16"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',wallet:'<path d="M3 7V5h16v16H3V7Zm0 0h16M15 12h6v5h-6Z"/>',message:'<path d="M21 3H3v14h5l4 4 4-4h5Z"/><path d="M7 8h10M7 12h6"/>',leaf:'<path d="M20 3c0 10-2 17-10 17a7 7 0 0 1-7-7C3 5 10 3 20 3ZM5 18 16 7"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',edit:'<path d="m16 3 5 5L9 20l-6 1 1-6ZM13 6l5 5"/>'};
const ico=(name)=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${iconPaths[name]||iconPaths.bag}</svg>`;
const esc=(s)=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=(n)=>'₹'+Number(n).toLocaleString('en-IN',{maximumFractionDigits:0});
const button=(label,action,args='',cls='')=>`<button class="btn ${cls}" data-action="${action}" ${args}>${label}</button>`;
const pic=(id,cls='')=>{const photoId=product(id)?.photoId??(id%24);return `<div class="photo ${cls}" role="img" aria-label="${esc(product(id)?.name||'Home textile product')}" style="--x:${(photoId%6)*20}%;--y:${Math.floor(photoId/6)*100/3}%"></div>`;};
const seedProducts=()=>[
 ['Sage cotton bath towel','Towels',90,50,800,'70 × 140 cm · 500 GSM','Sage green'],['Blush cotton bath towel','Towels',94,50,650,'70 × 140 cm · 500 GSM','Blush pink'],['Hotel white bath towel','Towels',88,100,1200,'70 × 140 cm · 450 GSM','Ivory'],['Navy cotton hand towel','Towels',38,50,900,'40 × 60 cm · 400 GSM','Navy'],['Lilac everyday face towel','Towels',22,100,1500,'30 × 30 cm · 350 GSM','Lilac'],['Mustard kitchen towel','Kitchen linen',32,50,700,'40 × 60 cm · cotton','Mustard'],
 ['Terracotta stripe bedsheet','Bedsheets',310,20,260,'Double · 220 × 240 cm','Terracotta'],['Indigo floral bedsheet','Bedsheets',340,20,190,'Double · cotton · 2 pillow covers','Indigo'],['Sage botanical bedsheet','Bedsheets',365,20,300,'King · 240 × 260 cm','Sage'],['Peach paisley bedsheet','Bedsheets',295,20,220,'Double · 144 thread count','Peach'],['Ivory waffle blanket','Throws & blankets',420,15,140,'150 × 200 cm · cotton','Ivory'],['Burgundy fringed throw','Throws & blankets',280,20,180,'130 × 170 cm · woven','Burgundy'],
 ['Botanical linen cushion cover','Cushion covers',68,50,850,'40 × 40 cm · cover only','Natural'],['Terracotta velvet cushion cover','Cushion covers',75,50,600,'40 × 40 cm · zip closure','Terracotta'],['Geometric cotton cushion cover','Cushion covers',62,50,1100,'40 × 40 cm · cover only','Black / ivory'],['Mustard tufted cushion cover','Cushion covers',96,30,380,'45 × 45 cm · cover only','Mustard'],['Indigo block-print cushion cover','Cushion covers',82,50,450,'40 × 40 cm · cotton','Indigo'],['Blush plain cushion cover','Cushion covers',55,50,980,'40 × 40 cm · cover only','Blush'],
 ['Natural linen table runner','Table linen',140,25,320,'35 × 180 cm · linen blend','Natural'],['Moss cotton placemat set','Table linen',120,30,400,'Set of 4 · 35 cm round','Moss'],['White dinner napkin set','Table linen',105,30,550,'Set of 4 · 40 × 40 cm','White'],['Stripe cotton kitchen apron','Kitchen linen',85,30,270,'Adult · adjustable straps','Terracotta'],['Textured cotton bath mat','Towels',115,30,360,'50 × 80 cm · cotton','Beige'],['Quilted oven mitt set','Kitchen linen',98,30,290,'Mitt + pot holder · cotton','Sage']
].map((p,id)=>({id,name:p[0],category:p[1],price:p[2],moq:p[3],stock:p[4],spec:p[5],colour:p[6],supplier:id%3===0?'Panipat Loomworks':id%3===1?'Northline Textile Traders':'Karnal Home Wholesale',type:id%3===0?'Manufacturer':id%3===1?'Trading supplier':'Wholesaler',active:true}));
function seed(){return {version:1,products:seedProducts(),cart:[],saved:[],plan:'peruse',planUsed:0,service:'managed',feedSaved:[],feedPassed:[],toured:[],requests:[{id:'REQ-101',name:'Sage bath towels for my shop',productId:0,category:'Towels',qty:200,spec:'100% cotton, 500 GSM, 70 × 140 cm, sage green. New unused stock; consistent colour and weight.',kind:'Ready stock',date:'2026-10-18',budget:100,payment:'Advance is workable',baseline:20800,status:'Quotes ready',sampleApproved:false,messages:[{by:'Merchant',text:'Three illustrative routes are ready. Compare quantity, payment timing and the complete basket—not just unit price.'}],quotes:[{id:'Q-101',supplier:'Panipat Loomworks',type:'Manufacturer',price:90,moq:200,freight:600,sample:150,setup:0,loss:200,days:0,lead:5,stock:800,note:'New unused ready stock. Sample matches the specified 500 GSM towel.',requiresSample:true,confirmed:true},{id:'Q-102',supplier:'Karnal Home Wholesale',type:'Wholesaler',price:96,moq:50,freight:300,sample:0,setup:0,loss:100,days:30,lead:2,stock:450,note:'Mixed small lots available. Existing 30-day credit relationship assumed for this demo.',requiresSample:false,confirmed:true},{id:'Q-103',supplier:'Northline Textile Traders',type:'Trading supplier',price:94,moq:100,freight:650,sample:150,setup:0,loss:200,days:0,lead:6,stock:600,note:'Full specified quantity. Advance payment; sample required.',requiresSample:true,confirmed:true}]},{id:'REQ-102',name:'Botanical cushion covers with a simple print',productId:12,category:'Cushion covers',qty:100,spec:'Cotton-linen blend, 40 × 40 cm, hidden zip. One botanical screen print, natural base. Covers only. Sample approval required.',kind:'Bounded customisation',date:'2026-10-28',budget:95,payment:'Advance is workable',baseline:11500,status:'Awaiting quotes',sampleApproved:false,messages:[],quotes:[]}],orders:[]};}
let state;try{const stored=JSON.parse(localStorage.getItem(STORE));state=stored?.version===1&&Array.isArray(stored.products)&&Array.isArray(stored.requests)?stored:seed();}catch{state=seed();}
let role=null,view='home',filter='All products',query='',sort='recommended',onlySaved=false,selectedRequest='REQ-101',tourStep=-1,modalFocus=null;
function persist(){try{localStorage.setItem(STORE,JSON.stringify(state));}catch{toast('Your browser could not save this session. The demo still works until you close it.');}}
function product(id){return state.products.find(p=>p.id===Number(id));}
function request(id=selectedRequest){return state.requests.find(r=>r.id===id);}
function toast(text){const t=document.getElementById('toast');t.textContent=text;t.classList.add('visible');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>t.classList.remove('visible'),4000);}
function navigate(next){view=next;closeModal();render();window.scrollTo({top:0,behavior:'instant'});}
const categories=['All products','Towels','Bedsheets','Cushion covers','Table linen','Kitchen linen','Throws & blankets'];
function header(){return `<header class="topbar"><button class="text-link" data-action="landing" aria-label="Meesho Merchant home"><div class="brand"><strong>meesho</strong><span>merchant</span></div><span class="brand-demo">Concept demo · sample data</span></button><div class="top-actions"><span class="badge">Concept demo · sample data</span>${role?button(ico('spark')+'<span class="desktop-only">Walkthrough</span><span class="mobile-only">Guide</span>','tour','aria-label="Replay walkthrough"','secondary small')+button(ico('swap')+`<span class="desktop-only">Switch to </span><span class="switch-role">${role==='buyer'?'seller':'buyer'}</span>`,'switch',`aria-label="Switch to ${role==='buyer'?'seller':'buyer'}"`,'quiet small'):button('How it works','about','','secondary small')}${button(ico('help'),'demohelp','aria-label="Demo controls"','quiet small')}</div></header>`;}
function navItems(){return role==='buyer'?[['home','home','Discover'],['requests','request','My requests'],['cart','bag','My basket'],['orders','orders','Orders'],['plans','wallet','Buying assistance']]:[['home','home','Overview'],['feed','request','Buyer requests'],['inventory','grid','My stock'],['orders','orders','Orders'],['quotes','message','My quotes']];}
function sidebar(){return `<aside class="sidebar"><div class="identity"><div class="avatar">${role==='buyer'?'SH':'PL'}</div><div><strong>${role==='buyer'?'Sharma Home Store':'Demo supplier network'}</strong><small>${role==='buyer'?'Buyer · Karnal':'Seller side · Panipat / Karnal'}</small></div></div><nav class="navlist" aria-label="Main navigation">${navItems().map(([id,icon,label])=>`<button class="navitem ${view===id?'active':''}" data-action="nav" data-view="${id}">${ico(icon)}${label}${id==='cart'&&state.cart.length?`<span class="count">${state.cart.length}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><strong>One purchase. A better outcome.</strong><p>${role==='buyer'?'Buy the stock you need. Choose help only when the work is worth the fee.':'Find complete requests. Quote on your terms. Zero sales commission.'}</p>${button('Show me around '+ico('arrow'),'tour','','secondary small full')}</div><small class="muted">Panipat → Karnal pilot concept<br>All activity is simulated.</small></aside>`;}
function mobileNav(){return `<nav class="mobile-nav" aria-label="Mobile navigation">${navItems().map(([id,icon,label])=>`<button class="${view===id?'active':''}" data-action="nav" data-view="${id}">${ico(icon)}<span>${label}</span></button>`).join('')}</nav>`;}
function landing(){return `<main class="landing" id="main"><div class="welcome"><div><h1>Stock your shop.<br><em>Keep more from<br>every purchase.</em></h1><p>Find home textiles in quantities you can use. Compare the complete cost. Let Merchant handle the buying work when you need a hand.</p><div class="inline-note">${ico('check')}No passwords. No real payments. Explore both sides.</div><div class="entry-grid"><button class="entry" data-action="enter" data-role="buyer">${ico('bag')}<h3>I’m buying for my shop</h3><p>Browse stock, compare supplier quotes and try an assisted purchase.</p><span class="enter">Enter as buyer ${ico('arrow')}</span></button><button class="entry" data-action="enter" data-role="seller">${ico('orders')}<h3>I’m supplying stock</h3><p>List ready stock, find buyer requests and manage fulfilment.</p><span class="enter">Enter as seller ${ico('arrow')}</span></button></div><small class="muted">An interactive Meesho Merchant proposal. Not a live Meesho service.</small></div><div class="welcome-art" aria-label="Home textiles available in the demo">${pic(0)}${pic(6)}${pic(12)}${pic(18)}</div></div><section class="landing-explain"><div>${ico('grid')}<h3>Only the stock you need</h3><p>Start with ready stock. For simple customisation, send a complete specification instead.</p></div><div>${ico('wallet')}<h3>See the whole buying cost</h3><p>Goods, delivery, samples, payment timing and optional service are shown separately.</p></div><div>${ico('leaf')}<h3>Useful help, on your terms</h3><p>Basic discovery is free. Try a ₹299 buying assignment; a monthly plan can follow repeated use.</p></div></section><div class="demo-footer">Demo suppliers, product images, prices and histories are illustrative. Nothing is purchased, shipped or verified here.</div></main>`;}
function pageHead(title,desc,action=''){return `<div class="page-head"><div><h1>${title}</h1><p>${desc}</p></div>${action}</div>`;}
function productCard(p){return `<article class="product"><button class="image-button" data-action="product" data-id="${p.id}" aria-label="View ${esc(p.name)}">${pic(p.id)}</button><span class="ribbon badge ${p.id%3===0?'green':'pink'}">${p.id%3===0?'Ready stock':'Small lots'}</span><button class="save ${state.saved.includes(p.id)?'on':''}" data-action="save" data-id="${p.id}" aria-label="${state.saved.includes(p.id)?'Unsave':'Save'} ${esc(p.name)}" aria-pressed="${state.saved.includes(p.id)}">${ico('heart')}</button><div class="product-body"><p>${esc(p.type)} · ${esc(p.supplier)}</p><h3>${esc(p.name)}</h3><div class="spec-line">${esc(p.spec)}</div><div class="price">${money(p.price)} <small>at minimum / ${p.id===19||p.id===20||p.id===23?'set':'unit'}</small></div><div class="product-bottom"><small class="muted">Min. ${p.moq} · ${p.stock} in stock</small>${button('Add '+ico('plus'),'add',`data-id="${p.id}"`,'secondary small')}</div></div></article>`;}
function catalogue(home){let list=state.products.filter(p=>p.active&&(filter==='All products'||p.category===filter)&&(!onlySaved||state.saved.includes(p.id))&&`${p.name} ${p.category} ${p.spec} ${p.supplier} ${p.colour}`.toLowerCase().includes(query.toLowerCase()));if(sort==='low')list.sort((a,b)=>a.price-b.price);if(sort==='min')list.sort((a,b)=>a.moq-b.moq);return `${home?`<section class="hero"><div class="hero-copy"><h1>A better basket.<br>For the shop you already run.</h1><p>Fresh home textiles, useful quantities and clear buying terms. More sales aren’t a requirement.</p>${button('Compare an example basket '+ico('arrow'),'compare',`data-id="REQ-101"`)}</div><div class="hero-image">${pic(6)}<div class="floating">${ico('check')}Ready-stock home textiles</div></div></section><div class="stepsbar"><span>${ico('grid')}Find usable stock</span><span>${ico('request')}Compare complete terms</span><span>${ico('truck')}Choose optional buying help</span></div>`:''}<div class="section-title"><h2>Find your next replenishment</h2>${button('Request sourcing '+ico('plus'),'nav','data-view="newrequest"','secondary small')}</div><div class="toolbar"><label class="search">${ico('search')}<input id="search" aria-label="Search home textiles" placeholder="Search towels, cushion covers, suppliers…" value="${esc(query)}"></label><select id="sort" aria-label="Sort products"><option value="recommended" ${sort==='recommended'?'selected':''}>Recommended</option><option value="low" ${sort==='low'?'selected':''}>Price: low to high</option><option value="min" ${sort==='min'?'selected':''}>Smallest minimum</option></select></div><div class="filters" aria-label="Product categories">${categories.map(c=>`<button class="pillbutton ${filter===c&&!onlySaved?'active':''}" data-action="filter" data-category="${c}">${c}</button>`).join('')}<button class="pillbutton ${onlySaved?'active':''}" data-action="saved">${ico('heart')} Saved</button></div><p class="muted" style="font-size:12px;margin-bottom:15px">${list.length} products · Illustrative prices at minimum quantity · Open a product to explore bulk price breaks</p><div class="products" id="catalogue">${list.length?list.map(productCard).join(''):`<div class="empty wide">${ico('search')}<h3>No matching stock</h3><p>Try a broader search, or send a sourcing request with your specifications.</p>${button('Clear filters','clearfilters','','secondary')}</div>`}</div>`;}

const unitMoney=n=>'₹'+Number(n).toLocaleString('en-IN',{maximumFractionDigits:2});
function priceTiers(p){return [1,2,4,8].map((multiple,i)=>({qty:p.moq*multiple,discount:(p.discounts||[0,3,6,8])[i],price:Math.round(p.price*(1-(p.discounts||[0,3,6,8])[i]/100)*100)/100})).filter(t=>t.qty<=p.stock);}
function quantityPrice(p,qty){return priceTiers(p).filter(t=>t.qty<=qty).at(-1)?.price??p.price;}
function quantityWidget(p,qty,context){const tiers=priceTiers(p),next=tiers.find(t=>t.qty>qty),rate=quantityPrice(p,qty);return `<div class="quantity-pricing" data-product="${p.id}" data-context="${context}"><div class="quantity-controls"><div class="quantity-heading"><label for="quantity-${context}-${p.id}">Choose quantity</label><output class="quantity-value" for="quantity-${context}-${p.id}">${qty} units</output></div><input class="quantity-slider" id="quantity-${context}-${p.id}" aria-label="${esc(p.name)} quantity" type="range" min="${p.moq}" max="${p.stock}" step="1" value="${qty}" data-context="${context}" data-id="${p.id}"><div class="range-limits"><span>Minimum ${p.moq}</span><span>Stock ${p.stock}</span></div><div class="price-breaks" aria-label="Quantity price breaks">${tiers.map(t=>`<button class="price-break ${t.qty===tiers.filter(t=>t.qty<=qty).at(-1)?.qty?'selected':''}" data-action="tierqty" data-id="${p.id}" data-context="${context}" data-qty="${t.qty}"><span>${t.qty}+ units</span><strong>${unitMoney(t.price)}</strong><small>${t.discount?t.discount+'% lower':'Base price'}</small></button>`).join('')}</div><div class="quantity-costs" aria-live="polite"><span>Selected unit price<strong class="selected-unit">${unitMoney(rate)}</strong></span><span>Goods total<strong class="selected-goods">${money(rate*qty)}</strong></span></div></div><p class="quantity-next">${next?`Next price break at ${next.qty} units (${next.qty-qty} more).`:'Best listed unit price for this stock.'}</p><p class="definition">Illustrative all-unit pricing: the selected tier applies to every unit. Buy only what you need; a lower unit price can still mean a larger cash outlay. Freight and service are separate.</p></div>`;}
function setQuantity(widget,value){const p=product(widget.dataset.product),qty=Math.min(p.stock,Math.max(p.moq,Math.round(Number(value)||p.moq))),tiers=priceTiers(p),tier=tiers.filter(t=>t.qty<=qty).at(-1),next=tiers.find(t=>t.qty>qty),rate=quantityPrice(p,qty);widget.querySelector('input').value=qty;widget.querySelector('output').textContent=qty+' units';widget.querySelector('.selected-unit').textContent=unitMoney(rate);widget.querySelector('.selected-goods').textContent=money(rate*qty);widget.querySelector('.quantity-next').textContent=next?`Next price break at ${next.qty} units (${next.qty-qty} more).`:'Best listed unit price for this stock.';widget.querySelectorAll('.price-break').forEach(b=>b.classList.toggle('selected',Number(b.dataset.qty)===tier?.qty));if(widget.dataset.context==='cart'){state.cart.find(c=>c.id===p.id).qty=qty;persist();const t=cartTotals();document.querySelector(`[data-line-total="${p.id}"]`).textContent=money(rate*qty);for(const k of ['goods','freight','fee','total'])document.querySelector(`[data-basket-total="${k}"]`).textContent=money(t[k]);}else{document.querySelector('[data-action="addselected"]').dataset.qty=qty;document.querySelector('[data-action="addselected"]').textContent=`Add ${qty} units to basket`;}positionTour();}

function cartTotals(){const goods=state.cart.reduce((a,c)=>a+quantityPrice(product(c.id),c.qty)*c.qty,0),freight=state.cart.length?Math.max(300,Math.round(goods*.025)):0;const fee=serviceFee();return {goods,freight,fee,total:goods+freight+fee};}
function serviceFee(){return state.service==='self'?0:state.plan==='monthly'&&state.planUsed<4?0:299;}
function serviceChoices(){return `<h3>Would you like help with this purchase?</h3><label class="choice"><input type="radio" name="service" value="managed" ${state.service==='managed'?'checked':''}><div><strong>Let Merchant coordinate</strong><p>Supplier comparison, agreed specs, dispatch follow-up and receipt records.</p></div><span class="amount">${serviceFee()===0&&state.plan==='monthly'?'<small>Plan-covered</small>':'₹299'}</span></label><label class="choice"><input type="radio" name="service" value="self" ${state.service==='self'?'checked':''}><div><strong>I’ll coordinate myself</strong><p>Use basic discovery without buying assistance. No subscription required.</p></div><span class="amount">₹0</span></label>`;}
function cartView(){const t=cartTotals();return pageHead('Your buying basket','Buy only the quantities your shop needs. Minimums and available stock are checked before an order.')+(state.cart.length?`<div class="split"><section class="panel"><h2>${state.cart.length} selected products</h2>${state.cart.map(c=>{const p=product(c.id);return `<div class="basket-line"><div class="item-row">${pic(p.id,'thumb')}<div><h3>${esc(p.name)}</h3><p>${esc(p.spec)} · ${esc(p.supplier)}</p>${button('Remove','remove',`data-id="${p.id}"`,'quiet small')}</div><div class="money" data-line-total="${p.id}">${money(quantityPrice(p,c.qty)*c.qty)}</div></div>${quantityWidget(p,c.qty,'cart')}</div>`;}).join('')}<div class="notice" style="margin-top:20px">Stock is new and unused in this example. Different suppliers issue separate goods invoices. No unsold-stock buyback is included.</div></section><section class="panel basket-summary" id="tour-target"><div class="service-choices">${serviceChoices()}</div><div class="receipt"><div><span>Goods · paid to supplier(s)</span><strong data-basket-total="goods">${money(t.goods)}</strong></div><div><span>Freight · carrier estimate</span><strong data-basket-total="freight">${money(t.freight)}</strong></div><div><span>Merchant procurement work</span><strong data-basket-total="fee">${money(t.fee)}</strong></div><div class="total"><span>Demo payable</span><span data-basket-total="total">${money(t.total)}</span></div></div><p class="definition">Illustrative amounts include demo tax treatment; freight is an estimate, not a live quote. No card or bank details are collected.</p>${button('Review demo order '+ico('arrow'),'checkoutcart','','full')}<button class="text-link" data-action="nav" data-view="plans">When does a monthly plan make sense?</button></section></div>`:empty('Your basket is ready for a first purchase','Choose a product and add its minimum usable lot. You can change quantities before ordering.','Browse home textiles','home'));}
function empty(title,desc,label,next){return `<div class="panel empty">${ico('bag')}<h2>${title}</h2><p>${desc}</p>${button(label,'nav',`data-view="${next}"`)}</div>`;}
function requestsView(){return pageHead('Your sourcing requests','Describe an actual purchase. Suppliers respond with quantity, timing and complete commercial terms.',button('New request '+ico('plus'),'nav','data-view="newrequest"'))+`<section class="panel" id="tour-target">${state.requests.map(r=>`<article class="request-row">${pic(r.productId,'thumb')}<div class="info"><div class="row"><span class="request-kind">${esc(r.kind)}</span><span class="badge ${r.quotes.length?'green':'amber'}">${esc(r.status)}</span></div><h3>${esc(r.name)}</h3><p>${r.qty} units · Karnal · Needed by ${formatDate(r.date)}</p><small class="muted">${r.id} · ${r.quotes.length} quotes · ${r.sampleApproved?'Sample approved':'Sample approval where required'}</small></div>${button(r.quotes.length?'Compare quotes':'View request','compare',`data-id="${r.id}"`,'secondary small')}</article>`).join('')}</section>`;}
function formatDate(s){return new Date(s+'T12:00:00').toLocaleDateString('en-IN',{day:'numeric',month:'short'});}
function requestForm(){return pageHead('Tell us what you need','A complete brief helps suppliers give a usable quote. Ready stock comes first; simple customisation is optional.')+`<div class="split"><form class="panel" id="request-form"><div class="form-grid"><label class="field wide">Request title<input name="name" required maxlength="90" value="Cotton towels for my next replenishment"></label><label class="field">Category<select name="category">${categories.slice(1).map(c=>`<option>${c}</option>`).join('')}</select></label><label class="field">Buying route<select name="kind"><option>Ready stock</option><option>Bounded customisation</option></select></label><label class="field">Required quantity<input name="qty" type="number" min="1" max="10000" value="200" required><small>Use the quantity you can actually sell.</small></label><label class="field">Budget per unit (₹)<input name="budget" type="number" min="1" max="100000" value="100" required></label><label class="field">Required by<input name="date" type="date" value="2026-10-25" min="2026-10-05" required></label><label class="field">Payment needs<select name="payment"><option>Advance is workable</option><option>Need existing 30-day supplier credit</option></select></label><label class="field wide">Material, size, colours and finish<textarea name="spec" minlength="20" required maxlength="1200">100% cotton, 500 GSM, 70 × 140 cm, sage green. New unused stock, same colour and weight. Sample needed before bulk purchase.</textarea><small>For custom stock, specify one base product and a bounded change. A photo alone is not a manufacturing specification.</small></label><label class="field wide">Your current complete cost for this basket (₹)<input name="baseline" type="number" min="0" max="10000000" value="20800"><small>Optional. Include usable goods, delivery and cash-timing costs. Leave 0 if unknown; we will not invent a saving.</small></label></div><div class="form-actions">${button('Cancel','nav','data-view="requests"','secondary')}<button class="btn" type="submit">Publish demo request ${ico('arrow')}</button></div></form><aside class="panel"><h3>A request suppliers can act on</h3><div class="checklist"><div class="inline-note">${ico('check')}Exact specification and usable quantity</div><div class="inline-note">${ico('check')}A real required-by date</div><div class="inline-note">${ico('check')}Payment needs visible before quotation</div><div class="inline-note">${ico('check')}Sample approval for custom work</div></div><div class="notice" style="margin-top:25px">This request appears immediately in the seller demo. Switch roles to quote it. No information is sent to real suppliers.</div></aside></div>`;}
function quoteCost(r,q){const goods=r.qty*q.price+q.setup,credit=q.days>=30?0:goods*.18*30/365,fee=serviceFee();return {goods,credit,fee,payable:goods+q.freight+q.sample+fee,total:goods+q.freight+q.sample+fee+q.loss+credit};}
function eligible(r,q){return q.moq<=r.qty&&q.stock>=r.qty&&!(r.payment.includes('30-day')&&q.days<30);}
function compareView(){const r=request();if(!r)return requestsView();const feasible=r.quotes.filter(q=>eligible(r,q));const best=feasible.length?Math.min(...feasible.map(q=>quoteCost(r,q).total)):0;return pageHead('Compare the whole purchase','A lower unit price is useful only if quantity, quality, timing and payment terms also work.',button('My requests','nav','data-view="requests"','secondary small'))+`<div class="panel"><div class="request-row"><div class="thumb">${pic(r.productId)}</div><div class="info"><span class="badge pink">${esc(r.kind)} · ${r.id}</span><h2>${esc(r.name)}</h2><p>${r.qty} units · Need by ${formatDate(r.date)} · ${esc(r.payment)}</p></div></div><p>${esc(r.spec)}</p><div class="compare-heading"><label class="field">Your existing all-in basket cost (₹)<input id="baseline" type="number" min="0" max="10000000" value="${r.baseline}" aria-label="Existing all-in basket cost"></label><div class="actions">${button('Ask a question '+ico('message'),'messages',`data-id="${r.id}"`,'secondary small')}${r.quotes.length?button('Export comparison '+ico('download'),'exportquotes',`data-id="${r.id}"`,'secondary small'):''}</div></div><label class="comparison-option"><input id="credit-required" type="checkbox" ${r.payment.includes('30-day')?'checked':''}>I need an existing 30-day credit arrangement</label><p class="definition">Credit availability here is a scenario, not an approval. Opportunity cost uses an illustrative 18% annual rate for 30 days. Loss is a planning allowance, not insurance or a charge.</p></div>${r.quotes.length?`<div class="quote-grid" id="tour-target">${r.quotes.map(q=>{const c=quoteCost(r,q),fit=eligible(r,q),save=r.baseline-c.total,isBest=fit&&Math.abs(c.total-best)<.01;return `<article class="quote ${isBest?'best':''}"><div><span class="badge ${isBest?'pink':fit?'green':'amber'}">${isBest?'Lowest feasible full cost':fit?'Quantity / payment fit':'Does not fit this request'}</span><h3 style="margin-top:12px">${esc(q.supplier)}</h3><p style="font-size:12px;margin:5px 0">${esc(q.type)} · Demo business</p><div class="spec-line">MOQ ${q.moq} · ${q.lead}-day lead time<br>${q.days?`${q.days}-day existing credit`:'Advance payment'} · ${q.stock} units available</div><p style="font-size:12px">${esc(q.note)}</p></div><div class="receipt"><div><span>Goods + setup</span><strong>${money(c.goods)}</strong></div><div><span>Freight</span><strong>${money(q.freight)}</strong></div><div><span>Sample</span><strong>${money(q.sample)}</strong></div><div><span>Procurement work</span><strong>${money(c.fee)}</strong></div><div><span>Cash-timing allowance</span><strong>${money(c.credit)}</strong></div><div><span>Loss allowance</span><strong>${money(q.loss)}</strong></div><div class="total"><span>Full-cost model</span><span>${money(c.total)}</span></div>${r.baseline>0?`<div><span>${save>=0?'Model saving':'Higher than current route'}</span><strong style="color:${save>=0?'#24694e':'#a43948'}">${money(Math.abs(save))} (${(Math.abs(save)/r.baseline*100).toFixed(1)}%)</strong></div>`:'<small>No baseline supplied. No savings claim.</small>'}<small>Payable: ${money(c.payable)}. Allowances are not collected.</small></div><button class="btn ${isBest?'':'secondary'}" data-action="selectquote" data-request="${r.id}" data-quote="${q.id}" ${!fit?'disabled':''}>${fit?'Review this quote':'Change requirements to proceed'}</button></article>`;}).join('')}</div><div class="notice" style="margin-top:20px">Quotes and costs are illustrative. The factory may win on price; a wholesaler may win when credit or small mixed lots matter. No route is always best.</div>`:empty('This request is waiting for a quote','Switch to the seller side to submit one, or populate clearly marked sample quotes to explore the comparison.','Switch to seller','feed')+button('Add illustrative sample quotes','seedquotes',`data-id="${r.id}"`,'secondary')}<section class="panel section">${serviceChoices()}</section>`;}
function plansView(){return pageHead('Buying help when it earns its place','Discovery is free. Pay for a defined buying job, then choose a monthly plan only if you use it enough.')+`<div class="plan-grid" id="tour-target"><section class="panel"><span class="badge pink">Start with one purchase</span><h2 style="margin-top:15px">Pay per assignment</h2><div class="plan-price">₹299 <small>/ standard buying job</small></div><p>No monthly commitment. One agreed basket, a clear scope and a separate fee.</p><ul><li>Compare feasible supplier terms</li><li>Confirm quantity and specifications</li><li>Coordinate dispatch and receipt follow-up</li></ul>${button(state.plan==='peruse'?'Current demo choice':'Choose per-use demo','plan','data-plan="peruse"','secondary full')}</section><section class="panel"><span class="badge">For useful repeated work</span><h2 style="margin-top:15px">Monthly assistance</h2><div class="plan-price">₹999 <small>/ month · up to 4 jobs</small></div><p>Four per-use jobs cost ₹1,196. A monthly plan saves ₹197 at that frequency.</p><ul><li>The same standard procurement work</li><li>Four scoped assignments per demo cycle</li><li>Extra jobs: ₹299 each, optional</li></ul>${button(state.plan==='monthly'?`Demo active · ${state.planUsed}/4 jobs used`:'Activate simulated monthly plan','plan','data-plan="monthly"','full')}</section></div><div class="panel section"><h3>Choose by your actual buying frequency</h3><div class="table-wrap"><table><thead><tr><th>Jobs per month</th><th>Per-use total</th><th>Monthly plan</th><th>Lower fee</th></tr></thead><tbody><tr><td>1</td><td>₹299</td><td>₹999</td><td>Per-use</td></tr><tr><td>3</td><td>₹897</td><td>₹999</td><td>Per-use</td></tr><tr><td>4</td><td>₹1,196</td><td>₹999</td><td>Monthly, by ₹197</td></tr></tbody></table></div><div class="notice" style="margin-top:20px">Proposed demo pricing, not a launched service. Complex custom work needs its own scope and quote. Goods, samples and freight remain separate; no financing or guarantee is included.</div></div>`;}
function supplierHome(){const own=state.products.filter(p=>p.supplier==='Panipat Loomworks');return pageHead('Good stock. The right buying request.','Welcome to Panipat Loomworks. Find usable demand, quote on your own terms and supply with zero sales commission.',button('Add a stock listing '+ico('plus'),'listing','','secondary'))+`<section class="hero"><div class="hero-copy"><h1>Less guesswork.<br>More complete briefs.</h1><p>See quantity, specifications, deadline and payment needs before spending time on a quote.</p>${button('Explore buyer requests '+ico('arrow'),'nav','data-view="feed"')}</div><div class="hero-image">${pic(0)}<div class="floating">${ico('check')}0% supplier sales commission</div></div></section><div class="stats"><div class="stat"><span>Demo stock listings</span><strong>${own.filter(p=>p.active).length}</strong></div><div class="stat"><span>Buyer requests</span><strong>${state.requests.length}</strong></div><div class="stat"><span>Orders in this session</span><strong>${state.orders.length}</strong></div><div class="stat"><span>Sales commission</span><strong>₹0</strong></div></div><div class="split"><section class="panel" id="tour-target"><h2>Ready to quote</h2>${state.requests.slice(0,2).map(r=>`<div class="request-row">${pic(r.productId,'thumb')}<div class="info"><h3>${esc(r.name)}</h3><p>${r.qty} units · ${esc(r.kind)}</p>${button('View and quote','quoteform',`data-id="${r.id}"`,'secondary small')}</div></div>`).join('')}</section><section class="panel"><h3>Your work stays in your control</h3><p style="margin-top:12px">Saving a request is not accepting an order. Quote your minimum, price, payment terms and lead time. Confirm capacity after the buyer selects a quote.</p><div class="notice" style="margin-top:20px">You supply the goods. The buyer may separately pay Merchant for procurement work. Seller discovery and quoting have no sales commission in this proposal.</div></section></div>`;}
function feedView(){const list=state.requests.filter(r=>!state.feedPassed.includes(r.id));return pageHead('Buyer requests worth a closer look','A finite shortlist of requirements. Save, pass or quote—none of these actions commits you to supply.')+`<div class="spread" style="margin-bottom:20px"><span class="swipe-summary">${list.length} requests · <span class="saved-count">${state.feedSaved.length} saved</span></span>${button('Restore passed requests','restorefeed','','quiet small')}</div><section class="feed" id="tour-target">${list.map(r=>`<article class="demand-card"><div class="demand-head">${pic(r.productId)}<div><span class="badge ${r.kind==='Ready stock'?'green':'amber'}">${esc(r.kind)}</span><h3 style="margin-top:8px">${esc(r.name)}</h3><p style="font-size:12px;margin-top:5px">Buyer ${r.id.replace('REQ','BUY')} · Karnal</p></div></div><div class="demand-body"><p style="font-size:13px">${esc(r.spec)}</p><div class="demand-meta"><div><span>Usable quantity</span><strong>${r.qty} units</strong></div><div><span>Budget / unit</span><strong>${money(r.budget)} indicative</strong></div><div><span>Needed by</span><strong>${formatDate(r.date)}</strong></div><div><span>Payment needs</span><strong>${r.payment.includes('30')?'Existing 30-day credit':'Advance workable'}</strong></div></div><div class="inline-note">${ico('shield')}Quote-ready brief · not a confirmed order</div><div class="demand-actions" style="margin-top:20px">${button('Pass','passrequest',`data-id="${r.id}"`,'quiet small')}${button(ico('heart')+(state.feedSaved.includes(r.id)?'Saved':'Save'),'saverequest',`data-id="${r.id}"`,'secondary small')}${button('Prepare quote '+ico('arrow'),'quoteform',`data-id="${r.id}"`,'small')}</div><button class="text-link" data-action="messages" data-id="${r.id}">Ask a specification question</button></div></article>`).join('')}</section>${!list.length?empty('No remaining requests','Restore passed requests or switch to buyer to publish a new requirement.','Buyer view','newrequest'):''}`;}
function inventoryView(){const own=state.products.filter(p=>p.supplier==='Panipat Loomworks');return pageHead('Your ready-stock catalogue','Panipat Loomworks is the example stock owner here. Listing changes appear immediately on the buyer side.',button('Add listing '+ico('plus'),'listing'))+`<section class="panel" id="tour-target">${own.map(p=>`<div class="inventory-row">${pic(p.id)}<div><h3>${esc(p.name)}</h3><p>${esc(p.spec)} · MOQ ${p.moq}</p><p class="mobile-inventory-meta">${money(p.price)}/unit · ${p.stock} units available</p><span class="badge ${p.active?'green':'amber'}">${p.active?'Visible to buyers':'Paused'}</span></div><div class="price" style="font-size:18px">${money(p.price)}<small>/unit</small></div><div class="stock-num"><strong>${p.stock}</strong><p>in stock</p></div><div class="actions">${button(ico('edit'),'listing',`data-id="${p.id}" aria-label="Edit ${esc(p.name)}"`,'secondary small')}${button(p.active?'Pause':'Resume','togglelisting',`data-id="${p.id}"`,'quiet small')}</div></div>`).join('')}</section>`;}
function myQuotes(){const qs=state.requests.flatMap(r=>r.quotes.filter(q=>q.supplier==='Panipat Loomworks').map(q=>({r,q})));return pageHead('Your submitted quotes','Your terms remain private to the buyer in this demo. A quote is not a confirmed goods order.')+`<section class="panel">${qs.length?qs.map(({r,q})=>`<div class="request-row"><div class="info"><span class="badge">${q.id} · ${r.id}</span><h3>${esc(r.name)}</h3><p>${money(q.price)}/unit · MOQ ${q.moq} · ${q.lead} days · ${q.days?q.days+'-day terms':'Advance'}</p></div>${button('Review buyer view','buyercompare',`data-id="${r.id}"`,'secondary small')}</div>`).join(''):empty('No submitted quotes','Find a requirement you can actually supply and prepare a complete quote.','Explore requests','feed')}</section>`;}
function orderStage(o){return ['Awaiting capacity','Confirmed','Packed','Dispatched','Received'].indexOf(o.status);}
function ordersView(){return pageHead(role==='buyer'?'Your purchases, step by step':'Supplier network fulfilment',role==='buyer'?'Goods and service are separate. Follow the order, record receipt and raise a discrepancy.':'This demo workspace represents all listed suppliers, including mixed baskets. Simulate fulfilment here; every milestone updates the buyer view.')+`<section class="panel" id="tour-target">${state.orders.length?state.orders.map(o=>`<article class="order-block"><div class="spread"><div><div class="order-title"><h3>${esc(o.title)}</h3><span class="badge ${o.status==='Received'?'green':'pink'}">${esc(o.status)}</span>${o.issue?'<span class="badge amber">Issue recorded</span>':''}</div><p style="font-size:13px;margin-top:5px">${o.id} · ${esc(o.supplier)} · ${o.qty} units · ${money(o.payable)} demo payable</p></div>${button('Order details','orderdetail',`data-id="${o.id}"`,'secondary small')}</div><div class="timeline">${['Awaiting capacity','Confirmed','Packed','Dispatched','Received'].map((s,i)=>`<div class="milestone ${orderStage(o)>=i?'done':''}"><span class="dot">${orderStage(o)>=i?ico('check'):i+1}</span>${s}</div>`).join('')}</div><div class="actions">${role==='seller'&&orderStage(o)<3?button(['Confirm capacity','Mark packed','Simulate dispatch'][Math.max(0,orderStage(o))],'advanceorder',`data-id="${o.id}"`,'small'):''}${role==='buyer'&&o.status==='Dispatched'?button('Record received goods','receive',`data-id="${o.id}"`,'small'):''}${role==='buyer'&&['Dispatched','Received'].includes(o.status)?button('Report a discrepancy','issue',`data-id="${o.id}"`,'secondary small'):''}${role==='buyer'&&o.status==='Received'?button('Build a repeat basket','reorder',`data-id="${o.id}"`,'secondary small'):''}</div>${o.issue?`<p class="notice amber" style="margin-top:15px">${esc(o.issue)} · Pending review; no refund is promised.</p>`:''}</article>`).join(''):empty('Your first demo order will appear here','Choose ready stock or compare a sourcing quote. Then switch roles to walk through capacity, packing and dispatch.','Browse '+(role==='buyer'?'stock':'requests'),role==='buyer'?'home':'feed')}</section>`;}
function render(){const app=document.getElementById('app');if(!role){app.innerHTML=header()+landing();return;}let content=role==='buyer'?(view==='home'?catalogue(true):view==='cart'?cartView():view==='requests'?requestsView():view==='newrequest'?requestForm():view==='compare'?compareView():view==='plans'?plansView():ordersView()):(view==='home'?supplierHome():view==='feed'?feedView():view==='inventory'?inventoryView():view==='quotes'?myQuotes():ordersView());app.innerHTML=header()+`<div class="shell">${sidebar()}<main class="main" id="main">${content}<div class="demo-footer">Meesho Merchant concept · Illustrative stock, quotes and orders · No real transactions</div></main></div>`+mobileNav();if(tourStep>=0)renderTour();}
function showModal(title,body,narrow=false){modalFocus=document.activeElement;const root=document.getElementById('overlay');root.innerHTML=`<div class="modal-backdrop"><section class="modal ${narrow?'narrow':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-header"><h2 id="modal-title">${title}</h2><button class="close" data-action="close" aria-label="Close dialog">${ico('close')}</button></header>${body}</section></div>`;const focus=root.querySelector('input,select,textarea,button');focus?.focus();}
function closeModal(){document.getElementById('overlay').innerHTML='';modalFocus?.focus();modalFocus=null;}
function showProduct(id){const p=product(id);showModal('Product and buying terms',`<div class="detail-hero">${pic(p.id)}<div><span class="badge green">New unused stock · Demo listing</span><h2 style="margin-top:15px">${esc(p.name)}</h2><p>${esc(p.supplier)} · ${esc(p.type)}</p><div class="specs"><div><span>Specification</span>${esc(p.spec)}</div><div><span>Colour</span>${esc(p.colour)}</div><div><span>Minimum lot</span>${p.moq} units</div><div><span>Available stock</span>${p.stock} units</div><div><span>Origin</span>Panipat / Karnal</div><div><span>Sample / remedies</span>Confirm before order</div></div><p style="font-size:13px">Photos illustrate the product family. Covers exclude inserts. Compare the exact sample and written specification before committing.</p>${quantityWidget(p,p.moq,'product')}<div class="actions">${button(`Add ${p.moq} units to basket`,'addselected',`data-id="${p.id}" data-qty="${p.moq}"`)}${button('Request a different spec','customproduct',`data-id="${p.id}"`,'secondary')}</div></div></div>`);}
function quoteForm(id){const r=request(id);showModal('Prepare a complete quote',`<p class="lead">${esc(r.name)} · ${r.qty} units · ${esc(r.payment)}</p><div class="notice" style="margin-bottom:20px">${esc(r.spec)}<br>Quoting does not accept the order. The buyer selects; you then confirm capacity.</div><form id="quote-form" data-id="${r.id}"><div class="form-grid"><label class="field">Unit price (₹)<input name="price" type="number" min="1" max="100000" step=".01" value="${r.budget*.9}" required></label><label class="field">Minimum units<input name="moq" type="number" min="1" max="10000" value="${r.qty}" required></label><label class="field">Available / feasible units<input name="stock" type="number" min="1" max="100000" value="${Math.max(r.qty,500)}" required></label><label class="field">Lead time (days)<input name="lead" type="number" min="1" max="90" value="5" required></label><label class="field">Freight (₹)<input name="freight" type="number" min="0" max="100000" value="600" required></label><label class="field">Sample cost (₹)<input name="sample" type="number" min="0" max="100000" value="150" required></label><label class="field">Setup cost (₹)<input name="setup" type="number" min="0" max="100000" value="${r.kind==='Ready stock'?0:1500}" required></label><label class="field">Payment terms<select name="days"><option value="0">Advance</option><option value="30">Existing 30-day arrangement</option></select></label><label class="field wide">Exact fit, deviations and remedy terms<textarea name="note" required minlength="10" maxlength="1000">Can supply the specified material, dimensions and quantity. Quote valid for 7 days. Report damaged or missing items within 5 days for review; no unsold-stock buyback.</textarea></label><label class="comparison-option wide"><input name="requiresSample" type="checkbox" checked>Sample approval required before bulk goods order</label></div><div class="form-actions"><button type="button" class="btn secondary" data-action="close">Cancel</button><button type="submit" class="btn">Submit demo quote</button></div></form>`);}
function reviewQuote(rid,qid){const r=request(rid),q=r.quotes.find(q=>q.id===qid);if(!eligible(r,q))return toast('This quote does not meet the current quantity or credit requirement.');const c=quoteCost(r,q);showModal('Review before the bulk order',`<p class="lead">${esc(q.supplier)} · ${r.qty} units · ${esc(r.name)}</p><div class="notice">Supplier legal identity: ${esc(q.supplier)}, demo business, Panipat/Karnal. In a live purchase, identity and binding written terms must be checked before goods payment.</div><div class="receipt"><div><span>Goods including setup</span><strong>${money(c.goods)}</strong></div><div><span>Freight</span><strong>${money(q.freight)}</strong></div><div><span>Sample</span><strong>${money(q.sample)}</strong></div><div><span>Optional procurement service</span><strong>${money(c.fee)}</strong></div><div class="total"><span>Demo payable</span><strong>${money(c.payable)}</strong></div></div>${q.requiresSample&&r.approvedQuote!==q.id?`<div class="notice amber"><strong>Sample approval comes first</strong>The selected specification must be approved before this demo lets you place a bulk order.</div><div class="actions">${button('Simulate sample review','sample',`data-request="${r.id}" data-quote="${q.id}"`,'full')}</div>`:`<div class="notice green"><strong>${q.requiresSample?'Sample approved for this specification':'Ready stock · sample not required by this quote'}</strong>Supplier must confirm capacity next. No real payment is collected.</div><div class="actions">${button('Place simulated goods order','placequote',`data-request="${r.id}" data-quote="${q.id}"`,'full')}</div>`}<p class="definition">Goods → supplier; freight → carrier; procurement fee → Merchant. Loss and cash-timing allowances are not collected. This is a demo, not escrow, credit approval or a guarantee.</p>`,true);}
function sampleModal(rid,qid){showModal('Approve the sample specification',`<p class="lead">Check the agreed specification before committing to bulk goods.</p><form id="sample-form" data-request="${rid}" data-quote="${qid}"><div class="checklist"><label><input type="checkbox" required>Material and GSM match the request</label><label><input type="checkbox" required>Dimensions, colour and finish match</label><label><input type="checkbox" required>Quantity, sample cost and remedies are understood</label></div><p class="definition">Simulated approval only. No physical sample has been inspected.</p><div class="form-actions"><button class="btn" type="submit">Record demo sample approval</button></div></form>`,true);}
function checkoutCart(){const t=cartTotals();showModal('Review your demo purchase',`<p class="lead">${state.cart.length} product lines · ${state.cart.reduce((s,c)=>s+c.qty,0)} units</p><div class="receipt"><div><span>Goods</span><strong>${money(t.goods)}</strong></div><div><span>Freight estimate</span><strong>${money(t.freight)}</strong></div><div><span>Optional procurement work</span><strong>${money(t.fee)}</strong></div><div class="total"><span>Demo payable</span><strong>${money(t.total)}</strong></div></div><div class="notice">Supplier identities and separate goods invoices are shown in the order. No real payment, stock reservation or purchase occurs.</div><div class="actions">${button('Place simulated order','placecart','','full')}</div>`,true);}
function addCart(id){const p=product(id);if(!p.active)return toast('This listing is paused.');let c=state.cart.find(c=>c.id===p.id);if((c?.qty||0)+p.moq>p.stock)return toast('That quantity exceeds the listed demo stock.');if(c)c.qty+=p.moq;else state.cart.push({id:p.id,qty:p.moq});persist();closeModal();render();toast(`${p.moq} units added. Open My basket to review.`);}
function createOrder(data){const o={id:'MM-'+(1001+state.orders.length),status:'Awaiting capacity',date:new Date().toISOString(),issue:'',managed:state.service==='managed',...data};state.orders.unshift(o);if(o.managed&&state.plan==='monthly'&&state.planUsed<4)state.planUsed++;persist();navigate('orders');toast('Simulated order created. Switch to seller to confirm capacity.');}
function listingModal(id){const p=id!==undefined?product(id):null;showModal(p?'Edit ready stock':'List ready stock',`<form id="listing-form" ${p?`data-id="${p.id}"`:''}><div class="form-grid"><label class="field wide">Product name<input name="name" maxlength="80" required value="${esc(p?.name||'Cotton kitchen towel')}" ></label><label class="field">Category<select name="category">${categories.slice(1).map(c=>`<option ${p?.category===c?'selected':''}>${c}</option>`).join('')}</select></label><label class="field">Price per unit (₹)<input name="price" type="number" min="1" max="100000" value="${p?.price||45}" required></label><label class="field">Minimum lot<input name="moq" type="number" min="1" max="10000" value="${p?.moq||50}" required></label><label class="field">Available units<input name="stock" type="number" min="1" max="100000" value="${p?.stock||500}" required></label><label class="field wide">Material, dimensions and finish<input name="spec" maxlength="150" value="${esc(p?.spec||'40 × 60 cm · 100% cotton')}" required></label><label class="field">Colour<input name="colour" maxlength="40" value="${esc(p?.colour||'Natural')}" required></label><label class="field">Demo photo<select name="photo"><option value="5">Kitchen towel</option><option value="0">Bath towel</option><option value="12">Cushion cover</option><option value="18">Table runner</option></select></label></div><fieldset class="tier-settings"><legend>Quantity price breaks</legend><p class="definition">Base price applies at the minimum lot. Set all-unit discounts below; only tiers within available stock appear to buyers.</p><div class="form-grid">${[2,4,8].map((multiple,i)=>`<label class="field">${multiple} × minimum: discount %<input name="discount${multiple}" type="number" min="0" max="30" step="0.1" value="${(p?.discounts||[0,3,6,8])[i+1]}" required></label>`).join('')}</div></fieldset><div class="notice" style="margin-top:18px">Unused stock only in this cohort. Returned or damaged inventory needs separate condition checks. Listing is illustrative, not verified.</div><div class="form-actions"><button class="btn" type="submit">Save demo listing</button></div></form>`,true);}
function messagesModal(id){const r=request(id);showModal('Clarify the buying requirement',`<p class="lead">${esc(r.name)} · In-demo messages only</p><div class="inbox">${r.messages.map(m=>`<div class="message ${m.by===role?'mine':''}"><small>${esc(m.by)}</small>${esc(m.text)}</div>`).join('')||'<p>No messages yet. Ask about material, size, packaging or timing.</p>'}</div><form id="message-form" data-id="${r.id}" style="margin-top:20px"><label class="field">Your specification question<textarea name="message" required minlength="3" maxlength="500" placeholder="Can you confirm the finished dimensions and packing units?"></textarea></label><p class="definition">Keep clarification here. Direct email/phone sharing is flagged in this demo; supplier legal identity remains visible before a purchase.</p><div class="form-actions"><button class="btn" type="submit">Send demo message</button></div></form>`,true);}
function orderDetail(id){const o=state.orders.find(o=>o.id===id);showModal(o.id+' · Order record',`<p class="lead">${esc(o.title)} · ${esc(o.status)}</p><div class="notice">${esc(o.supplier)} · Demo supplier(s), Panipat/Karnal. Goods invoice(s) are issued by each supplier. Merchant's procurement fee has a separate record.</div><div class="receipt"><div><span>Goods</span><strong>${money(o.goods)}</strong></div><div><span>Freight</span><strong>${money(o.freight)}</strong></div><div><span>Sample</span><strong>${money(o.sample||0)}</strong></div><div><span>Procurement fee</span><strong>${money(o.fee)}</strong></div><div class="total"><span>Demo payable</span><strong>${money(o.payable)}</strong></div></div><p>${o.managed?'Merchant coordination selected.':'Buyer self-coordination selected.'} ${o.fee===0&&o.managed?'Assignment covered by the previously selected demo plan.':''}</p><div class="actions">${button('Download demo order record '+ico('download'),'downloadorder',`data-id="${o.id}"`,'secondary full')}</div><p class="definition">This record is not a tax invoice, payment receipt or evidence of actual dispatch.</p>`,true);}
function download(name,content,type='text/plain'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}

const buyerTour=[
 ['home','Your shop’s next purchase','Browse stock you already need. Open any product to explore its specifications, minimum quantity and bulk prices. More sales are not a requirement.','.product:first-child'],
 ['requests','Start with a clear requirement','This example is a real purchase need in the story: 200 towels, a clear specification and a deadline. Your new requests also appear on the supplier side.','.request-row:first-child'],
 ['cart','Move the slider. See the price change.','Try 50, 100, 200 and 400 units, or tap a price break. Watch unit price and total goods cost change together. Bigger lots should fit your shop’s need.','.basket-line .quantity-controls'],
 ['compare','Compare the complete buying terms','Try this credit checkbox. When the shop needs existing 30-day credit, prepaid quotes stop fitting. These quotes are for the exact requested quantity; catalogue price breaks do not replace them.','.comparison-option'],
 ['cart','Choose the work you want help with','Choose Merchant coordination for a proposed ₹299 assignment, or coordinate yourself for ₹0 service fee. Goods and freight stay separate.','.service-choices'],
 ['plans','Let repeated value earn a monthly plan','Compare per-use help with the proposed ₹999 plan for up to four jobs. The monthly plan only makes sense when you use enough assignments.','.plan-grid'],
 ['orders','Follow the order on both sides','After placing a simulated order, switch to seller to confirm, pack and dispatch. Return as buyer to record receipt. Use this role switch to explore both sides.','[data-action="switch"]']
];
const sellerTour=[
 ['home','Supply on your own terms','Find complete buyer requests. Selling has zero sales commission; buyers separately choose optional procurement work.','[data-action="nav"][data-view="feed"]'],
 ['feed','Read the buyer’s exact requirement','Check quantity, specification, deadline and payment needs before quoting. Save or pass a request without committing to supply.','.demand-card:first-child'],
 ['feed','Prepare a complete quote','Use Prepare quote to enter your price, minimum lot, sample cost, freight and timing. Your response appears in the buyer’s comparison.','[data-action="quoteform"]'],
 ['inventory','Set stock and quantity prices','Use Edit to change the base price, stock, minimum lot and discounts at 2, 4 and 8 times the minimum. Buyers see those tiers immediately.','.inventory-row [data-action="listing"]'],
 ['orders','Confirm capacity before dispatch','Orders appear here after a buyer places one. Confirm capacity, then pack and dispatch. Buyer receipt is a separate milestone.','.order-block, .empty'],
 ['quotes','Explore the buyer’s decision','Switch to buyer to compare the quote you submitted. Both workspaces share the same simulated activity in this browser.','[data-action="switch"]']
];
function startTour(){clearTimeout(window.toastTimer);document.getElementById('toast').classList.remove('visible');tourStep=0;advanceTour(0);}
function advanceTour(delta){const steps=role==='buyer'?buyerTour:sellerTour;tourStep+=delta;if(tourStep>=steps.length){tourStep=-1;if(!state.toured.includes(role))state.toured.push(role);persist();render();toast('You’re ready to explore. Replay Walkthrough anytime.');return;}if(tourStep<0)tourStep=0;view=steps[tourStep][0];if(view==='compare')selectedRequest='REQ-101';if(role==='buyer'&&view==='cart'&&!state.cart.length){state.cart=[{id:0,qty:200}];persist();}closeModal();render();const target=tourTarget();if(target){const r=target.getBoundingClientRect();const top=window.scrollY+r.top-(window.innerWidth<=760?85:115);window.scrollTo({top:Math.max(0,top),behavior:'instant'});}else window.scrollTo({top:0,behavior:'instant'});requestAnimationFrame(positionTour);}
function tourTarget(){const steps=role==='buyer'?buyerTour:sellerTour;const selector=steps[tourStep]?.[3];if(!selector)return null;return [...document.querySelectorAll(selector)].find(el=>el.getBoundingClientRect().width>0)??document.querySelector('#main .panel, #main .hero');}
function renderTour(){const steps=role==='buyer'?buyerTour:sellerTour,s=steps[tourStep];if(!s)return;document.getElementById('app').insertAdjacentHTML('beforeend',`<div class="tour-spotlight" aria-hidden="true"></div><aside class="tour" aria-label="${role} walkthrough"><div class="tour-top"><span>${role==='buyer'?'Buyer':'Supplier'} walkthrough · ${tourStep+1} of ${steps.length}</span><button class="close" data-action="tourstop" aria-label="Exit walkthrough">${ico('close')}</button></div><h3>${s[1]}</h3><p>${s[2]}</p><div class="tour-progress">${steps.map((_,i)=>`<span class="${i<=tourStep?'on':''}"></span>`).join('')}</div><div class="tour-foot">${button(tourStep?'Back':'Explore on my own',tourStep?'tourback':'tourstop','','quiet small')}${button(tourStep===steps.length-1?'Finish walkthrough':'Next '+ico('arrow'),'tournext','','small')}</div></aside>`);requestAnimationFrame(positionTour);}
function positionTour(){const guide=document.querySelector('.tour'),ring=document.querySelector('.tour-spotlight'),target=tourTarget();if(!guide||!ring||!target)return;const r=target.getBoundingClientRect(),w=innerWidth,h=innerHeight,mobile=w<=760,pad=6;const inHeader=!!target.closest('.topbar'),top=Math.max(inHeader?4:72,r.top-pad),bottom=Math.min(h-(mobile?72:12),r.bottom+pad);ring.style.cssText=`left:${Math.max(4,r.left-pad)}px;top:${top}px;width:${Math.min(w-8,r.width+pad*2)}px;height:${Math.max(0,bottom-top)}px`;guide.style.bottom='auto';const gh=guide.offsetHeight,gw=guide.offsetWidth;let x,y;if(mobile){x=12;y=Math.min(h-gh-80,Math.max(82,r.bottom+16));if(y<r.bottom+10&&r.top-gh-16>=76)y=r.top-gh-16;}else{if(r.right+gw+24<w){x=r.right+18;y=Math.max(82,Math.min(r.top,h-gh-16));}else if(r.left-gw-24>0){x=r.left-gw-18;y=Math.max(82,Math.min(r.top,h-gh-16));}else{x=w-gw-24;y=r.bottom+18;if(y+gh>h-16)y=Math.max(82,r.top-gh-18);}}guide.style.left=x+'px';guide.style.right='auto';guide.style.top=y+'px';}
let tourFrame;for(const event of ['resize','scroll'])window.addEventListener(event,()=>{if(tourStep<0)return;cancelAnimationFrame(tourFrame);tourFrame=requestAnimationFrame(positionTour);},{passive:true});
function enter(next){role=next;view='home';tourStep=-1;render();if(!state.toured.includes(next))startTour();}
document.addEventListener('click',event=>{const b=event.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;switch(a){case'enter':enter(b.dataset.role);break;case'landing':role=null;tourStep=-1;closeModal();render();break;case'nav':tourStep=-1;navigate(b.dataset.view);break;case'switch':tourStep=-1;closeModal();enter(role==='buyer'?'seller':'buyer');break;case'close':closeModal();break;case'tour':closeModal();startTour();break;case'tournext':advanceTour(1);break;case'tourback':advanceTour(-1);break;case'tourstop':tourStep=-1;if(!state.toured.includes(role))state.toured.push(role);persist();render();break;case'filter':filter=b.dataset.category;onlySaved=false;render();break;case'clearfilters':filter='All products';query='';onlySaved=false;render();break;case'saved':onlySaved=!onlySaved;render();break;case'save':{const n=Number(id);state.saved=state.saved.includes(n)?state.saved.filter(x=>x!==n):[...state.saved,n];persist();render();break;}case'product':showProduct(id);break;case'add':addCart(id);break;case'addselected':{const p=product(id),qty=Number(b.dataset.qty),c=state.cart.find(c=>c.id===p.id);if((c?.qty||0)+qty>p.stock)return toast('Combined basket quantity exceeds available stock.');if(c)c.qty+=qty;else state.cart.push({id:p.id,qty});persist();closeModal();render();toast(qty+' units added. Open My basket to review quantity pricing.');break;}case'tierqty':setQuantity(b.closest('.quantity-pricing'),b.dataset.qty);break;case'remove':state.cart=state.cart.filter(c=>c.id!==Number(id));persist();render();break;case'qty':{const c=state.cart.find(c=>c.id===Number(id)),p=product(id),q=c.qty+Number(b.dataset.delta);if(q<p.moq)return toast('Use Remove to remove the product. Minimum is '+p.moq+' units.');if(q>p.stock)return toast('Quantity exceeds the available demo stock.');c.qty=q;persist();render();break;}case'compare':selectedRequest=id;navigate('compare');break;case'customproduct':{const p=product(id);navigate('newrequest');const f=document.getElementById('request-form');f.elements.namedItem('name').value=p.name+' · my specification';f.elements.namedItem('category').value=p.category;f.elements.namedItem('spec').value=p.spec+', '+p.colour+'. Confirm usable quantity and exact finish.';f.elements.namedItem('qty').value=p.moq;f.elements.namedItem('budget').value=p.price;f.elements.namedItem('baseline').value=0;break;}case'seedquotes':{const r=request(id);const p=r.budget*.9;r.quotes=[{id:'Q-'+Date.now(),supplier:'Panipat Loomworks',type:'Manufacturer',price:p,moq:r.qty,freight:600,sample:150,setup:r.kind==='Ready stock'?0:1500,loss:200,days:0,lead:5,stock:r.qty*3,note:'Illustrative sample quote, not a supplier response. Exact specifications require sample approval.',requiresSample:true,confirmed:true},{id:'Q-'+(Date.now()+1),supplier:'Karnal Home Wholesale',type:'Wholesaler',price:r.budget*.97,moq:Math.min(50,r.qty),freight:300,sample:0,setup:r.kind==='Ready stock'?0:1800,loss:100,days:30,lead:3,stock:r.qty*2,note:'Illustrative quote with assumed existing credit. No approval is implied.',requiresSample:r.kind!=='Ready stock',confirmed:true}];r.status='Quotes ready';persist();render();break;}case'quoteform':quoteForm(id);break;case'buyercompare':role='buyer';selectedRequest=id;tourStep=-1;navigate('compare');break;case'selectquote':reviewQuote(b.dataset.request,b.dataset.quote);break;case'sample':sampleModal(b.dataset.request,b.dataset.quote);break;case'placequote':{const r=request(b.dataset.request),q=r.quotes.find(q=>q.id===b.dataset.quote);if(!eligible(r,q)||q.requiresSample&&r.approvedQuote!==q.id)return toast('Please resolve quote fit and sample approval first.');const c=quoteCost(r,q);r.status='Order placed';createOrder({title:r.name,supplier:q.supplier,qty:r.qty,goods:c.goods,freight:q.freight,sample:q.sample,fee:c.fee,payable:c.payable,items:[{id:r.productId,qty:r.qty}],requestId:r.id});break;}case'checkoutcart':if(state.cart.length)checkoutCart();break;case'placecart':{if(!state.cart.length)return;const invalid=state.cart.some(c=>!product(c.id)?.active||c.qty<product(c.id).moq||c.qty>product(c.id).stock);if(invalid)return toast('A listing changed. Review minimums, visibility and stock before ordering.');const t=cartTotals(),items=structuredClone(state.cart);state.cart=[];createOrder({title:items.length===1?product(items[0].id).name:'Mixed home-textile basket',supplier:[...new Set(items.map(c=>product(c.id).supplier))].join(' + '),qty:items.reduce((s,c)=>s+c.qty,0),goods:t.goods,freight:t.freight,sample:0,fee:t.fee,payable:t.total,items});break;}case'plan':{if(b.dataset.plan==='monthly'){showModal('Try the monthly plan in this demo',`<p>₹999 per demo cycle covers up to four standard buying assignments. Goods, freight and samples remain separate. There is no real billing or automatic renewal.</p><div class="notice" style="margin-top:18px">This resets the simulated plan’s four-job allowance. No payment is collected.</div><div class="actions">${button('Confirm simulated ₹999 plan','activateplan','','full')}</div>`,true);}else{state.plan='peruse';persist();render();toast('Per-use selected. No monthly plan is needed.');}break;}case'activateplan':state.plan='monthly';state.planUsed=0;state.service='managed';persist();closeModal();render();toast('Simulated monthly plan activated. No money charged.');break;case'listing':listingModal(id===undefined?undefined:Number(id));break;case'togglelisting':{const p=product(id);p.active=!p.active;persist();render();toast(p.active?'Listing is visible to buyers.':'Listing paused in buyer discovery.');break;}case'passrequest':state.feedPassed.push(id);persist();render();break;case'saverequest':state.feedSaved=state.feedSaved.includes(id)?state.feedSaved.filter(x=>x!==id):[...state.feedSaved,id];persist();render();break;case'restorefeed':state.feedPassed=[];persist();render();break;case'messages':messagesModal(id);break;case'advanceorder':{const o=state.orders.find(o=>o.id===id);o.status=['Confirmed','Packed','Dispatched'][Math.max(0,orderStage(o))]||o.status;persist();render();toast('Demo milestone updated. The buyer sees the same status.');break;}case'receive':showModal('Record received goods',`<form id="receive-form" data-id="${id}"><p>Check the agreed quantity and specification. Receipt here is simulated.</p><div class="checklist"><label><input type="checkbox" required>All agreed units received</label><label><input type="checkbox" required>Usable specification and condition checked</label></div><div class="form-actions"><button class="btn" type="submit">Confirm demo receipt</button></div></form>`,true);break;case'issue':showModal('Record a discrepancy',`<form id="issue-form" data-id="${id}"><label class="field">What needs review?<select name="type"><option>Missing units</option><option>Damaged goods</option><option>Specification mismatch</option><option>Late consignment</option></select></label><label class="field" style="margin-top:15px">Details<textarea name="note" required minlength="10" maxlength="500" placeholder="Record affected quantities and the agreed specification."></textarea></label><p class="definition">This records a demo case for review. It does not promise refunds, insurance or unsold-stock buyback.</p><div class="form-actions"><button class="btn" type="submit">Record demo issue</button></div></form>`,true);break;case'orderdetail':orderDetail(id);break;case'downloadorder':{const o=state.orders.find(o=>o.id===id);download(o.id+'-DEMO.txt',`MEESHO MERCHANT — DEMO ORDER RECORD\nNOT A TAX INVOICE OR PAYMENT RECEIPT\n${o.id}\n${o.title}\nSupplier(s): ${o.supplier}\nQuantity: ${o.qty}\nGoods: ${money(o.goods)}\nFreight: ${money(o.freight)}\nSample: ${money(o.sample||0)}\nProcurement fee: ${money(o.fee)}\nDemo payable: ${money(o.payable)}\nStatus: ${o.status}\nAll data illustrative.`);break;}case'reorder':{const o=state.orders.find(o=>o.id===id);state.cart=structuredClone(o.items);persist();navigate('cart');toast('Review current stock and terms before a repeat order.');break;}case'exportquotes':{const r=request(id);const csvrow=v=>'"'+String(v).replaceAll('"','""')+'"';download(r.id+'-DEMO-comparison.csv',[['DEMO DATA ONLY','Supplier','Goods + setup','Freight','Sample','Procurement fee','Cash allowance','Loss allowance','Full model cost','Payable'],...r.quotes.map(q=>{const c=quoteCost(r,q);return ['Illustrative',q.supplier,c.goods,q.freight,q.sample,c.fee,c.credit.toFixed(2),q.loss,c.total.toFixed(2),c.payable];})].map(row=>row.map(csvrow).join(',')).join('\n'),'text/csv');break;}case'about':showModal('A buying assistant for your shop',`<p>Find the stock you need in a usable quantity. Compare full buying terms, including the value of credit and an intermediary. Choose optional help for an agreed buying assignment.</p><div class="receipt"><div><span>Basic discovery</span><strong>Free</strong></div><div><span>Standard assignment</span><strong>₹299 proposed</strong></div><div><span>Up to 4 jobs/month</span><strong>₹999 proposed</strong></div><div><span>Supplier sales commission</span><strong>0%</strong></div></div><p>No new lending, escrow or inventory guarantee is demonstrated. This is a concept prototype with sample data.</p>`,true);break;case'demohelp':showModal('Ready for a presentation',`<p>Choose either role, replay the walkthrough, and switch sides to show the connected journey. This browser remembers demo activity.</p><div class="checklist"><div>Buyer → towel request → compare → approve sample → simulated order</div><div>Seller → orders → confirm capacity → pack → dispatch</div><div>Buyer → orders → record receipt → repeat purchase</div><div>Buyer → new request → seller quote → buyer comparison</div></div><div class="actions">${role?button('Replay walkthrough','tour','','secondary full'):''}${button('Reset all demo activity','resetconfirm','','danger full')}</div><p class="definition">No external accounts, live messages, payments or shipping. Reset restores the 24 products and two example requests.</p>`,true);break;case'resetconfirm':showModal('Reset this demo?',`<p>This clears only the prototype’s local products, requests, quotes, plan selection and orders. Your project research files are unaffected.</p><div class="actions">${button('Keep my session','close','','secondary')}${button('Reset demo','reset','','danger')}</div>`,true);break;case'reset':state=seed();persist();role=null;view='home';tourStep=-1;filter='All products';query='';onlySaved=false;closeModal();render();toast('Demo reset. Choose a role to start again.');break;}});
document.addEventListener('input',event=>{if(event.target.matches('.quantity-slider')){setQuantity(event.target.closest('.quantity-pricing'),event.target.value);return;}if(event.target.id==='search'){query=event.target.value;const pos=event.target.selectionStart;render();const s=document.getElementById('search');s.focus();s.setSelectionRange(pos,pos);}});
document.addEventListener('change',event=>{const el=event.target;if(el.name==='category'&&el.closest('#request-form')){const f=el.closest('form'),p=state.products.find(p=>p.category===el.value);f.elements.namedItem('spec').value=p?`${p.spec}, ${p.colour}. New unused stock. Confirm material, dimensions, finish and sample before bulk purchase.`:'';}if(el.id==='sort'){sort=el.value;render();}if(el.name==='service'){state.service=el.value;persist();render();}if(el.id==='baseline'){const n=Number(el.value);request().baseline=Number.isFinite(n)?Math.max(0,n):0;persist();render();}if(el.id==='credit-required'){request().payment=el.checked?'Need existing 30-day supplier credit':'Advance is workable';persist();render();}});
document.addEventListener('submit',event=>{const f=event.target;if(!f.id.endsWith('-form'))return;event.preventDefault();if(!f.reportValidity())return;const d=Object.fromEntries(new FormData(f));if(f.id==='request-form'){const first=state.products.find(p=>p.category===d.category);const id='REQ-'+(103+state.requests.filter(r=>r.id!=='REQ-101'&&r.id!=='REQ-102').length);state.requests.unshift({...d,id,qty:Number(d.qty),budget:Number(d.budget),baseline:Number(d.baseline)||0,productId:first?.id||0,status:'Awaiting quotes',sampleApproved:false,quotes:[],messages:[]});persist();selectedRequest=id;navigate('requests');toast('Demo request published. Switch to seller to prepare a quote.');}if(f.id==='quote-form'){const r=request(f.dataset.id);r.quotes.push({id:'Q-'+Date.now(),supplier:'Panipat Loomworks',type:'Manufacturer',price:Number(d.price),moq:Number(d.moq),stock:Number(d.stock),lead:Number(d.lead),freight:Number(d.freight),sample:Number(d.sample),setup:Number(d.setup),days:Number(d.days),loss:200,note:d.note,requiresSample:r.kind!=='Ready stock'||!!d.requiresSample,confirmed:false});r.status='Quotes ready';persist();closeModal();navigate('quotes');toast('Demo quote submitted. Switch to buyer to compare it.');}if(f.id==='sample-form'){const r=request(f.dataset.request);r.sampleApproved=true;r.approvedQuote=f.dataset.quote;persist();reviewQuote(r.id,f.dataset.quote);}if(f.id==='listing-form'){const n=Number(d.moq),stock=Number(d.stock),discounts=[0,Number(d.discount2),Number(d.discount4),Number(d.discount8)];if(discounts.some((v,i)=>!Number.isFinite(v)||v<0||v>30||(i&&v<discounts[i-1])))return toast('Discounts must increase or stay equal with quantity, between 0% and 30%.');if(n>stock)return toast('Minimum lot must not exceed your available stock.');let p=f.dataset.id!==undefined?product(f.dataset.id):null;if(p)Object.assign(p,{name:d.name,category:d.category,price:Number(d.price),moq:n,stock,discounts,spec:d.spec,colour:d.colour});else{const id=Math.max(...state.products.map(p=>p.id))+1;state.products.push({id,name:d.name,category:d.category,price:Number(d.price),moq:n,stock,discounts,spec:d.spec,colour:d.colour,supplier:'Panipat Loomworks',type:'Manufacturer',active:true,photoId:Number(d.photo)});}persist();closeModal();navigate('inventory');toast('Stock saved. It is now available on the buyer side.');}if(f.id==='message-form'){if(/\b\S+@\S+\.\S+\b|(?:\+91[\s-]?)?\b\d{10}\b/.test(d.message))return toast('Please keep direct contact details out of this demo message. Specifications are welcome.');const r=request(f.dataset.id);r.messages.push({by:role,text:d.message});persist();messagesModal(r.id);toast('Message saved in the shared demo request.');}if(f.id==='receive-form'){state.orders.find(o=>o.id===f.dataset.id).status='Received';persist();closeModal();render();toast('Demo receipt recorded. You can now build a repeat basket.');}if(f.id==='issue-form'){state.orders.find(o=>o.id===f.dataset.id).issue=d.type+': '+d.note;persist();closeModal();render();toast('Demo discrepancy recorded for review.');}});
document.addEventListener('keydown',event=>{const overlay=document.getElementById('overlay');if(event.key==='Escape'){if(overlay.innerHTML)closeModal();else if(tourStep>=0){tourStep=-1;render();}}if(event.key==='Tab'&&overlay.innerHTML){const focusables=[...overlay.querySelectorAll('button,input,select,textarea,a[href]')].filter(e=>!e.disabled);const first=focusables[0],last=focusables.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}});
document.getElementById('overlay').addEventListener('click',e=>{if(e.target.classList.contains('modal-backdrop'))closeModal();});
render();
